## Code Example
```csharp
// Minimal illustration for GET endpoint
public async Task<IActionResult> GetCatalog(string tenantId, string productId)
{
    var key = $"{tenantId}:{productId}";
    var cached = await _cache.GetStringAsync(key);
    if (cached != null) return new OkObjectResult(JsonConvert.DeserializeObject<Product>(cached));

    var tbl = _table.GetTableReference("Catalog");
    var op = TableOperation.Retrieve<ProductEntity>(tenantId, productId);
    var res = await tbl.ExecuteAsync(op);
    var item = (ProductEntity)res.Result;
    if (item == null) return new NotFoundResult();

    var prod = item.ToProduct();
    await _cache.SetStringAsync(key, JsonConvert.SerializeObject(prod), new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(300) });
    return new OkObjectResult(prod);
}
```

